import * as THREE from 'three';

const $=s=>document.querySelector(s), canvas=$('#game');
const ui={overlay:$('#overlay'),content:$('#overlay-content'),start:$('#start-button'),top:$('#topbar'),mission:$('#mission'),health:$('#health-panel'),cross:$('#crosshair'),hint:$('#controls-hint'),touch:$('#touch-controls'),objective:$('#objective'),count:$('#objective-count'),world:$('#world-name'),number:$('#world-number'),healthFill:$('#health-fill'),healthLabel:$('#health-label'),slots:[...document.querySelectorAll('#artifact-slots i')],toast:$('#toast'),prompt:$('#prompt'),boss:$('#boss-panel'),bossHealth:$('#boss-health'),bossPhase:$('#boss-phase'),hit:$('#hit-flash'),hurt:$('#hurt-flash')};
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;
const scene=new THREE.Scene();scene.background=new THREE.Color(0x080d18);scene.fog=new THREE.FogExp2(0x080d18,.022);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,180);camera.position.set(0,7,12);
scene.add(new THREE.HemisphereLight(0x8db6d2,0x15101c,1.5));const sun=new THREE.DirectionalLight(0xe4f4ff,2.1);sun.position.set(-7,13,6);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-22;sun.shadow.camera.right=22;sun.shadow.camera.top=22;sun.shadow.camera.bottom=-22;scene.add(sun);
const fill=new THREE.PointLight(0x22bdb5,9,24);fill.position.set(2,7,-4);scene.add(fill);
const mats={floor:new THREE.MeshStandardMaterial({color:0x18202a,roughness:.92}),dark:new THREE.MeshStandardMaterial({color:0x101925,roughness:.68,metalness:.42}),metal:new THREE.MeshStandardMaterial({color:0x374555,roughness:.35,metalness:.72}),teal:new THREE.MeshStandardMaterial({color:0x44ddd1,emissive:0x0d625c,emissiveIntensity:2,roughness:.24}),purple:new THREE.MeshStandardMaterial({color:0x9f4cff,emissive:0x4515a0,emissiveIntensity:1.6}),red:new THREE.MeshStandardMaterial({color:0xff354c,emissive:0x87121e,emissiveIntensity:2.4}),sand:new THREE.MeshStandardMaterial({color:0x927653,roughness:1}),stone:new THREE.MeshStandardMaterial({color:0x4c494a,roughness:.9}),glass:new THREE.MeshStandardMaterial({color:0x141c2f,emissive:0x192950,emissiveIntensity:.75,metalness:.55,roughness:.3})};
const worlds=[['ABANDONED CITY','Find three access keys'],['DIGITAL NIGHTMARE','Destroy the corrupted echoes'],['FORGOTTEN DESERT','Recover the buried relic'],['COSMIC ABYSS','Activate the three portal anchors'],['CITADEL // ULTITANKIST_RUT','Defeat ULTITANKIST_RUT']];
let game={started:false,active:false,world:0,hp:100,fragments:0,objective:0,entities:[],shots:[],decor:[],boss:null,phase:0,fire:false,mouse:{x:innerWidth/2,y:innerHeight/2},last:0,elapsed:0,invuln:0,dash:0,toastTimer:0,gameOver:false};
const player={mesh:null,velocity:new THREE.Vector3(),position:new THREE.Vector3(0,0,4),radius:.46};
const keys={};
function mesh(geo,mat,parent=scene){const m=new THREE.Mesh(geo,mat);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function box(x,y,z,sx,sy,sz,mat,parent=scene){const m=mesh(new THREE.BoxGeometry(sx,sy,sz),mat,parent);m.position.set(x,y,z);return m}
function cylinder(x,y,z,r1,r2,h,mat,parent=scene,segments=12){const m=mesh(new THREE.CylinderGeometry(r1,r2,h,segments),mat,parent);m.position.set(x,y,z);return m}
function sphere(x,y,z,r,mat,parent=scene){const m=mesh(new THREE.SphereGeometry(r,16,12),mat,parent);m.position.set(x,y,z);return m}
function clearScene(){for(const o of [...game.entities,...game.shots,...game.decor])scene.remove(o);game.entities=[];game.shots=[];game.decor=[];if(player.mesh){scene.remove(player.mesh);player.mesh=null}if(game.boss){scene.remove(game.boss.group);game.boss=null}}
function makePlayer(){const root=new THREE.Group();scene.add(root);const body=mesh(new THREE.CapsuleGeometry(.39,.55,4,8),mats.metal,root);body.position.y=.75;const chest=box(0,.82,0,.62,.48,.42,mats.dark,root);const visor=box(0,1.02,-.23,.38,.12,.08,mats.teal,root);const head=sphere(0,1.3,0,.27,mats.metal,root);head.scale.set(1,.82,.9);for(const x of [-.24,.24]){cylinder(x,.28,0,.14,.12,.28,mats.dark,root);sphere(x,.28,-.01,.07,mats.teal,root)}const pack=box(0,.77,.3,.38,.5,.18,mats.dark,root);root.position.copy(player.position);player.mesh=root;return root}
function addEntity(obj,type,health=1){obj.userData={...(obj.userData||{}),type,health,maxHealth:health};game.entities.push(obj);return obj}
function addShot(obj,velocity,enemy=false,damage=20){obj.userData={velocity,enemy,damage,life:5};game.shots.push(obj)}
function seeded(n){let x=Math.sin(n*127.1+game.world*311.7)*43758.5453;return x-Math.floor(x)}
function makeArena(){clearScene();game.objective=0;game.hp=100;game.phase=0;game.boss=null;player.position.set(0,0,4);player.velocity.set(0,0,0);scene.fog.color.setHex(game.world===2?0x17120d:game.world===3?0x08091d:0x080d18);scene.fog.density=game.world===1?.028:game.world===2?.018:.022;scene.background.setHex(game.world===2?0x100b1b:game.world===3?0x090b20:0x080d18);fill.color.setHex(game.world===2?0xa026ff:game.world===3?0x684dff:0x22bdb5);
 const floorMat=game.world===2?mats.sand:game.world===1?mats.dark:mats.floor;const ground=mesh(new THREE.PlaneGeometry(58,58,1,1),floorMat);ground.rotation.x=-Math.PI/2;ground.position.y=-.12;ground.receiveShadow=true;game.decor.push(ground);
 // radial arena markings and luminous perimeter
 for(let i=0;i<16;i++){const a=i*Math.PI/8,x=Math.cos(a)*13,z=Math.sin(a)*13;const p=box(x,.015,z,.055,.025,7,mats.teal);p.rotation.y=-a;game.decor.push(p)}
 const ring=mesh(new THREE.TorusGeometry(13,.035,6,96),game.world===4?mats.red:mats.teal);ring.rotation.x=Math.PI/2;ring.position.y=.02;game.decor.push(ring);
 for(let i=0;i<34;i++){const a=seeded(i+1)*Math.PI*2,r=14+seeded(i+90)*12,x=Math.cos(a)*r,z=Math.sin(a)*r;let d;if(game.world===0){const h=2+seeded(i+20)*7;d=box(x,h/2,z,1.8+seeded(i+5)*2,h,1.5+seeded(i+6)*2,seeded(i+8)>.7?mats.glass:mats.dark);if(seeded(i+4)>.55){const win=box(x,h*.55,z-(.82),.8,.16,.03,mats.teal);game.decor.push(win)}}else if(game.world===1){d=box(x,.75,z,1.2,1.5,1.2,mats.glass);d.rotation.y=seeded(i+2)}else if(game.world===2){d=cylinder(x,.7,z,.3,.8,1.4,mats.stone);d.rotation.z=(seeded(i+2)-.5)*.8}else if(game.world===3){d=sphere(x,.6,z,.5,mats.dark);d.scale.set(1.3,.55,1)}else{d=box(x,1.1,z,1.5,2.2,1.5,mats.dark)}game.decor.push(d)}
 // broken pillars and platforms around combat space
 for(let i=0;i<8;i++){const a=i*Math.PI/4;const x=Math.cos(a)*10,z=Math.sin(a)*10;const p=box(x,.8,z,.8,1.6,.8,game.world===4?mats.red:mats.metal);p.rotation.y=a;game.decor.push(p);const cap=box(x,1.65,z,.95,.08,.95,game.world===4?mats.red:mats.teal);game.decor.push(cap)}
 for(let i=0;i<75;i++){const st=sphere((seeded(i+55)-.5)*46,2+seeded(i+71)*15,(seeded(i+88)-.5)*46,.035+seeded(i+9)*.055,mats.teal);st.material= new THREE.MeshBasicMaterial({color:game.world===4?0xff4555:0x74d9ed});game.decor.push(st)}
 makePlayer();if(game.world===4)makeBoss();else makeWorldObjectives();
 ui.world.textContent=worlds[game.world][0];ui.number.textContent=String(game.world+1).padStart(2,'0');ui.objective.textContent=worlds[game.world][1];ui.count.textContent=objectiveCounter();ui.boss.classList.toggle('hidden',game.world!==4);updateHUD();
}
function objectiveCounter(){if(game.world===0)return `${Math.min(game.objective,3)} / 3`;if(game.world===1)return `${Math.min(game.objective,5)} / 5`;if(game.world===2)return `${Math.min(game.objective,1)} / 1`;if(game.world===3)return `${Math.min(game.objective,3)} / 3`;return 'PHASE '+(game.phase+1)}
function makeWorldObjectives(){
 if(game.world===0){for(let i=0;i<3;i++){const g=makeRelic(0x55eee1);g.position.set((i-1)*4,.65,-2+((i%2)*2));addEntity(g,'objective');}}
 if(game.world===1){for(let i=0;i<5;i++){const e=makeEnemy(i);e.position.set((i%3-1)*4,0,-3-Math.floor(i/3)*4);addEntity(e,'enemy',1)}}
 if(game.world===2){const g=makeRelic(0xffc46a);g.position.set(0,.72,-5);addEntity(g,'objective')}
 if(game.world===3){for(let i=0;i<3;i++){const g=makeAnchor(i);g.position.set((i-1)*5,.12,-4);addEntity(g,'anchor')};createPortal()}
}

