 if(game.world===3){for(let i=0;i<3;i++){const g=makeAnchor(i);g.position.set((i-1)*5,.12,-4);addEntity(g,'anchor')};createPortal()}
}
function makeRelic(color){const g=new THREE.Group();const m=new THREE.MeshStandardMaterial({color,emissive:color,emissiveIntensity:1.9,metalness:.6,roughness:.2});const core=mesh(new THREE.OctahedronGeometry(.42,0),m,g);core.rotation.y=.4;const r=mesh(new THREE.TorusGeometry(.62,.025,7,32),m,g);r.rotation.x=Math.PI/2;const r2=mesh(new THREE.TorusGeometry(.72,.018,6,32),m,g);r2.rotation.y=.8;g.userData.core=core;return g}
function makeEnemy(index){const g=new THREE.Group();const body=sphere(0,1.05,0,.62,mats.purple,g);body.scale.set(1,.8,.82);for(let n=0;n<3;n++){const ring=mesh(new THREE.TorusGeometry(.8+n*.13,.035,6,24),mats.teal,g);ring.rotation.x=n*.8;ring.rotation.z=n*.45}for(let s of [-1,1]){const eye=sphere(s*.23,1.2,-.48,.08,mats.red,g)}return g}
function makeAnchor(index){const g=new THREE.Group();const base=cylinder(0,.2,0,.8,.95,.4,mats.dark,g);const ring=mesh(new THREE.TorusGeometry(.66,.055,8,36),mats.teal,g);ring.rotation.x=Math.PI/2;ring.position.y=.5;const crystal=mesh(new THREE.OctahedronGeometry(.42),mats.metal,g);crystal.position.y=.9;const glow=sphere(0,.9,0,.18,mats.teal,g);g.userData.ring=ring;g.userData.crystal=crystal;return g}
function createPortal(){const g=new THREE.Group();const frame=mesh(new THREE.TorusGeometry(2.2,.15,10,64),mats.metal,g);frame.position.set(0,2.4,-9);const inner=mesh(new THREE.CircleGeometry(1.95,48),new THREE.MeshBasicMaterial({color:0x1b56a0,transparent:true,opacity:.32,side:THREE.DoubleSide}),g);inner.position.set(0,2.4,-9.04);for(let i=0;i<9;i++){const b=box(-2.2+i*.55,4.7,-9,.025,.5,.025,mats.teal,g);b.rotation.z=(i-4)*.08}game.decor.push(g)}
function makeBoss(){const group=new THREE.Group();const red=game.phase===2;const body=mesh(new THREE.IcosahedronGeometry(1.35,1),red?mats.red:mats.metal,group);body.position.y=2.15;body.scale.set(1.25,1.05,.82);const chest=box(0,2.1,-.82,1.05,.65,.25,red?mats.red:mats.dark,group);const head=sphere(0,3.2,-.1,.55,mats.dark,group);const eye=sphere(0,3.22,-.58,.29,red?mats.red:mats.teal,group);const crown=mesh(new THREE.TorusGeometry(1.18,.065,8,48),red?mats.red:mats.teal,group);crown.position.y=2.18;crown.rotation.x=Math.PI/2;for(let s of [-1,1]){const arm=box(s*1.35,2.05,0,.42,1.15,.5,red?mats.red:mats.metal,group);arm.rotation.z=s*.2;const orb=sphere(s*1.38,1.35,-.1,.29,red?mats.red:mats.teal,group);const leg=box(s*.52,.55,0,.46,1,.58,mats.dark,group);leg.rotation.z=s*.06}for(let i=0;i<6;i++){const spike=mesh(new THREE.ConeGeometry(.15,.55,5),red?mats.red:mats.teal,group);spike.position.set((i-2.5)*.35,3.85,0);spike.rotation.z=(i-2.5)*-.2}group.position.set(0,0,-6);scene.add(group);game.boss={group,hp:100,max:100,attack:0,teleport:4,attackKind:0,copies:[],arenaCracked:false};}
function setToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(game.toastTimer);game.toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2100)}
function updateHUD(){ui.healthFill.style.width=Math.max(0,game.hp)+'%';ui.healthLabel.textContent=Math.max(0,Math.ceil(game.hp));ui.slots.forEach((s,i)=>s.classList.toggle('filled',i<game.fragments));ui.count.textContent=objectiveCounter()}

