function updateHUD(){ui.healthFill.style.width=Math.max(0,game.hp)+'%';ui.healthLabel.textContent=Math.max(0,Math.ceil(game.hp));ui.slots.forEach((s,i)=>s.classList.toggle('filled',i<game.fragments));ui.count.textContent=objectiveCounter()}
function showOverlay(title,copy,button,extra='',action){game.active=false;ui.overlay.classList.remove('dismissed');ui.content.classList.add('mode-card');ui.content.innerHTML=`<div class="title-kicker"><span class="status-pip"></span> ${extra||'MISSION UPDATE'}</div><h1>${title}</h1><p class="title-copy">${copy}</p><div class="card-worlds">${worlds.map((w,i)=>`<span class="world-chip ${i<game.world?'done':i===game.world?'current':''}">${String(i+1).padStart(2,'0')} · ${w[0].split(' //')[0]}</span>`).join('')}</div><button id="continue-button" class="primary-button"><span>${button}</span><b>↗</b></button><div class="title-footer"><span>RELIC FRAGMENTS ${game.fragments} / 4</span><span>TRANSMISSION // ${String(game.world+1).padStart(3,'0')}</span><span>NO SIGNAL IS EVER TRULY LOST</span></div>`;$('#continue-button').onclick=action;}
function beginGame(){game.started=true;game.active=true;ui.overlay.classList.add('dismissed');ui.content.classList.remove('mode-card');[ui.top,ui.mission,ui.health,ui.cross,ui.hint].forEach(x=>x.classList.remove('hidden'));ui.touch.classList.toggle('hidden',!matchMedia('(hover: none)').matches);makeArena();setToast('SIGNAL ACQUIRED // SECTOR 01')}
function completeWorld(){if(game.world<4){if(game.world<4)game.fragments=Math.min(4,game.world+1);updateHUD();const next=game.world+1;const copy=game.world===3?'All four fragments resonate. The citadel gate is open. ULTITANKIST_RUT is waiting.':`World cleared. Ancient fragment ${game.fragments} of 4 recovered. The signal points deeper into the void.`;showOverlay(game.world===3?'THE GATE IS OPEN':'FRAGMENT RECOVERED',copy,game.world===3?'ENTER THE CITADEL':'CONTINUE',`WORLD ${String(game.world+1).padStart(2,'0')} COMPLETE`,()=>{game.world=next;beginGame()});}else{ui.boss.classList.add('hidden');showOverlay('THE GAME ISN’T OVER',"ULTITANKIST_RUT hasn't finished his game yet...",'PLAY AGAIN','SECRET ENDING // SIGNAL STILL ACTIVE',()=>{game.world=0;game.fragments=0;beginGame()});}}
function finishObjective(){game.objective++;updateHUD();if(game.world===0&&game.objective>=3)completeWorld();if(game.world===1&&game.objective>=5)completeWorld();if(game.world===2&&game.objective>=1)completeWorld();if(game.world===3&&game.objective>=3)completeWorld()}
function targetPoint(){const ndc=new THREE.Vector2(game.mouse.x/innerWidth*2-1,-game.mouse.y/innerHeight*2+1);const ray=new THREE.Raycaster();ray.setFromCamera(ndc,camera);const plane=new THREE.Plane(new THREE.Vector3(0,1,0),0);const pt=new THREE.Vector3();ray.ray.intersectPlane(plane,pt);if(!pt||Math.abs(pt.x)>40||Math.abs(pt.z)>40)return new THREE.Vector3(0,0,-6);return pt}
function fireShot(){if(!game.active||game.fireCooldown>0)return;game.fireCooldown=.23;const from=player.position.clone().add(new THREE.Vector3(0,1.05,0));const aim=targetPoint();let candidates=game.entities.filter(e=>e.userData.type==='enemy');if(game.boss)candidates=[game.boss.group,...candidates];let target=null,best=Infinity;for(const e of candidates){const p=e.getWorldPosition(new THREE.Vector3());const d=p.distanceTo(aim);if(d<best){best=d;target=e}}if(target&&best<4.2){if(target===game.boss.group)damageBoss(11);else damageEnemy(target)}const to=target?target.getWorldPosition(new THREE.Vector3()):aim;const dir=to.sub(from).normalize();const end=from.clone().addScaledVector(dir,Math.min(18,from.distanceTo(aim)));const line=mesh(new THREE.CylinderGeometry(.025,.025,from.distanceTo(end),5),new THREE.MeshBasicMaterial({color:game.phase===2?0xff4555:0x64fff2,transparent:true,opacity:.85}));line.position.copy(from).add(end).multiplyScalar(.5);line.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),dir);game.shots.push(line);line.userData={life:.12,velocity:new THREE.Vector3(),enemy:false,beam:true};ui.hit.classList.remove('active');void ui.hit.offsetWidth;ui.hit.classList.add('active')}
function damageEnemy(e){if(!e.parent)return;const pos=e.position.clone();scene.remove(e);game.entities=game.entities.filter(x=>x!==e);const burst=sphere(pos.x,1,pos.z,.35,mats.teal);game.decor.push(burst);setTimeout(()=>{scene.remove(burst);game.decor=game.decor.filter(x=>x!==burst)},250);finishObjective()}
function damageBoss(amount){const b=game.boss;if(!b)return;b.hp=Math.max(0,b.hp-amount);ui.bossHealth.style.width=b.hp+'%';const phase=b.hp<=33?2:b.hp<=66?1:0;if(phase!==game.phase){game.phase=phase;setBossPhase();}if(b.hp<=0){game.boss=null;completeWorld()}}
function setBossPhase(){if(!game.boss)return;const b=game.boss,group=b.group;ui.bossPhase.textContent=game.phase===0?'PHASE I — NORMAL FORM':game.phase===1?'PHASE II — GLITCH FORM':'PHASE III — ABSOLUTE FORM';const color=game.phase===2?mats.red:game.phase===1?mats.purple:mats.teal;group.traverse(o=>{if(o.isMesh&&o.material!==mats.dark) o.material=color});scene.fog.density=game.phase===2?.035:.022;if(game.phase===1){for(let i=0;i<2;i++){const c=new THREE.Group();c.position.set(i?3.5:-3.5,0,-6);for(const obj of group.children){const copy=obj.clone();c.add(copy)}scene.add(c);b.copies.push(c)}setToast('GLITCH FORM // DIGITAL COPIES DETECTED')}if(game.phase===2){setToast('ABSOLUTE FORM // ARENA BREACH');for(let i=0;i<8;i++){const crack=box((seeded(i+300)-.5)*20,.03,(seeded(i+400)-.5)*18,.08,.04,3,mats.red);crack.rotation.y=seeded(i+500);game.decor.push(crack)}b.arenaCracked=true;game.hp=Math.min(game.hp,80);updateHUD();setTimeout(()=>setToast('“You’ve reached the very end... But you didn’t think you could defeat ULTITANKIST_RUT, did you?”'),1000)}}

