function onKey(e,down){keys[e.code]=down;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(!down)return;if(e.code==='Space'){game.dash=.22;const direction=new THREE.Vector3((keys.KeyD?1:0)-(keys.KeyA?1:0),0,(keys.KeyS?1:0)-(keys.KeyW?1:0));if(direction.lengthSq())player.position.addScaledVector(direction.normalize(),1.7)}if(e.code==='Escape'&&game.started){if(game.active){showOverlay('PAUSED','The signal is holding. Take a breath before the next transmission.','RESUME','TRANSMISSION HELD',()=>{game.active=true;ui.overlay.classList.add('dismissed')})}else if(!game.gameOver){game.active=true;ui.overlay.classList.add('dismissed')}}if(e.code==='KeyE'&&game.world!==3){const e0=game.entities.find(x=>x.userData.type==='objective'&&x.position.distanceTo(player.position)<1.4);if(e0){scene.remove(e0);game.entities=game.entities.filter(x=>x!==e0);finishObjective()}}}
window.addEventListener('keydown',e=>onKey(e,true));window.addEventListener('keyup',e=>onKey(e,false));window.addEventListener('mousemove',e=>{game.mouse.x=e.clientX;game.mouse.y=e.clientY});window.addEventListener('mousedown',e=>{if(e.button===0){game.fire=true;fireShot()}});window.addEventListener('mouseup',()=>game.fire=false);canvas.addEventListener('contextmenu',e=>e.preventDefault());
ui.start.addEventListener('click',beginGame);ui.touch.querySelectorAll('[data-move]').forEach(btn=>{const code={forward:'KeyW',back:'KeyS',left:'KeyA',right:'KeyD'}[btn.dataset.move];btn.addEventListener('pointerdown',e=>{e.preventDefault();keys[code]=true;btn.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>btn.addEventListener(ev,()=>keys[code]=false))});$('#touch-fire').addEventListener('pointerdown',e=>{e.preventDefault();game.fire=true;fireShot()});['pointerup','pointercancel','pointerleave'].forEach(ev=>$('#touch-fire').addEventListener(ev,()=>game.fire=false));$('#touch-dash').addEventListener('pointerdown',e=>{e.preventDefault();game.dash=.22});
function frame(now){requestAnimationFrame(frame);const dt=Math.min(.04,(now-game.last)/1000||0);game.last=now;update(dt);if(player.mesh&&!game.active){camera.position.lerp(new THREE.Vector3(0,7.8,12),.025);camera.lookAt(0,1,-1)}for(const o of game.decor){if(o.userData?.core)o.rotation.y+=dt*.7}renderer.render(scene,camera)}
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight)});
makeArena();requestAnimationFrame(frame);

